Running command: cat > /tmp/test_pem.c << 'EOF'
#include <openssl/bio.h>
#include <openssl/err.h>
#include <openssl/mem.h>
#include <openssl/pem.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <pem_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *buf = malloc(len);
    fread(buf, 1, len, f);
    fclose(f);

    char *name, *header;
    unsigned char *pem_data;
    long pem_len;

    BIO *bio = BIO_new_mem_buf(buf, len);

    if (PEM_read_bio(bio, &name, &header, &pem_data, &pem_len) == 1) {
        OPENSSL_free(name);
        OPENSSL_free(header);
        OPENSSL_free(pem_data);
    }

    BIO_free(bio);
    ERR_clear_error();
    free(buf);
    return 0;
}
EOF
